// Separation of Reconciler and Platform Renderer Architecture
class PlatformAgnosticReconciler {
  constructor(hostConfig) {
    this.host = hostConfig;
  }

  // Simulating Fiber reconciliation into Host platform instances
  render(virtualElement, hostContainer) {
    const instance = this.createFiberInstance(virtualElement);
    this.host.appendChild(hostContainer, instance);
    return instance;
  }

  createFiberInstance(element) {
    if (typeof element === 'string' || typeof element === 'number') {
      return this.host.createTextInstance(String(element));
    }

    const instance = this.host.createInstance(element.type, element.props);
    if (element.children) {
      for (const child of element.children) {
        const childInstance = this.createFiberInstance(child);
        this.host.appendChild(instance, childInstance);
      }
    }
    return instance;
  }
}

