// Formal Mutation HostConfig Lifecycle Engine
class FormalHostConfigEngine {
  constructor() {
    this.mutationLogs = [];
  }

  // HostConfig: Node Allocators
  createInstance(type, props) {
    const instance = { id: Math.random().toString(36).slice(2, 7), type, props: { ...props }, children: [] };
    this.mutationLogs.push('createInstance [' + type + '] #' + instance.id);
    return instance;
  }

  createTextInstance(text) {
    const textInstance = { id: Math.random().toString(36).slice(2, 7), text };
    this.mutationLogs.push('createTextInstance "' + text + '" #' + textInstance.id);
    return textInstance;
  }

  appendInitialChild(parent, child) {
    parent.children.push(child);
    this.mutationLogs.push('appendInitialChild: added #' + child.id + ' into #' + parent.id);
  }

  // HostConfig: Two-Phase Diffing & Mutation
  prepareUpdate(instance, oldProps, newProps) {
    const diff = {};
    let hasChanges = false;
    for (const key in newProps) {
      if (newProps[key] !== oldProps[key]) {
        diff[key] = newProps[key];
        hasChanges = true;
      }
    }
    return hasChanges ? diff : null;
  }

  commitUpdate(instance, updatePayload) {
    this.mutationLogs.push('commitUpdate #' + instance.id + ': ' + JSON.stringify(updatePayload));
    Object.assign(instance.props, updatePayload);
  }
}

