// Virtual Node Graph with Layout Calculation & ASCII Tree Serialization
class VirtualNode {
  constructor(type, props = {}) {
    this.type = type;
    this.props = props;
    this.children = [];
    this.layout = { x: 0, y: 0, width: 0, height: 0 };
  }

  appendChild(child) {
    this.children.push(child);
  }

  computeLayout(startX = 0, startY = 0) {
    this.layout.x = startX;
    this.layout.y = startY;

    let currentY = startY + 1; // Top padding
    let maxWidth = (this.props.title ? this.props.title.length + 4 : 20);

    for (const child of this.children) {
      if (child instanceof VirtualNode) {
        child.computeLayout(startX + 2, currentY);
        currentY += child.layout.height;
        maxWidth = Math.max(maxWidth, child.layout.width + 4);
      } else if (typeof child === 'string') {
        maxWidth = Math.max(maxWidth, child.length + 4);
        currentY += 1;
      }
    }

    this.layout.width = maxWidth;
    this.layout.height = Math.max(currentY - startY + 1, 3);
  }

  renderAscii(indent = '') {
    const lines = [];
    lines.push(indent + '+-- <' + this.type + '> [' + this.layout.width + 'x' + this.layout.height + ']');
    for (const child of this.children) {
      if (child instanceof VirtualNode) {
        lines.push(child.renderAscii(indent + '    '));
      } else {
        lines.push(indent + '    "' + child + '"');
      }
    }
    return lines.join('\n');
  }
}

