// Headless Terminal ANSI Reconciler Engine
class TerminalAnsiRenderer {
  constructor() {
    this.colors = {
      green: '[32m',
      red: '[31m',
      cyan: '[36m',
      yellow: '[33m',
      reset: '[0m'
    };
  }

  colorize(text, colorName) {
    const code = this.colors[colorName];
    if (!code) return text;
    return '\x1b' + code + text + '\x1b' + this.colors.reset;
  }

  renderToString(node) {
    if (typeof node === 'string') return node;

    if (node.type === 'text') {
      const content = node.children.map(c => this.renderToString(c)).join('');
      return node.props.color ? this.colorize(content, node.props.color) : content;
    }

    if (node.type === 'box') {
      const innerContent = node.children.map(c => this.renderToString(c)).join(' | ');
      const title = node.props.title ? ' ' + node.props.title + ' ' : '';
      const borderLine = '='.repeat(40);
      return borderLine + '\n| ' + title + innerContent + '\n' + borderLine;
    }

    return '';
  }
}

