// Complete Custom Renderer Lifecycle: Scheduling, Diffing & Committing
class EnterpriseTerminalRenderer {
  constructor() {
    this.frameBuffer = '';
    this.renderPassCount = 0;
    this.activeTree = null;
  }

  mount(vdom) {
    this.activeTree = JSON.parse(JSON.stringify(vdom));
    this.renderPassCount++;
    this.frameBuffer = this.renderToScreen(this.activeTree);
  }

  update(diffPayload) {
    this.renderPassCount++;
    // Apply update to active tree
    Object.assign(this.activeTree.props, diffPayload);
    this.frameBuffer = this.renderToScreen(this.activeTree);
  }

  renderToScreen(node) {
    const title = node.props.title || 'DASHBOARD';
    const status = node.props.status || 'UNKNOWN';
    const memory = node.props.memoryMb || 0;

    return '[FRAME #' + this.renderPassCount + ' - ' + title + ']\n' +
           'Status: ' + status + ' | Heap: ' + memory + ' MB\n' +
           '----------------------------------------';
  }
}

